inventory-node.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://doraops.dev/schemas/inventory-node.schema.json",
  "title": "DORAOps Inventory Node",
  "oneOf": [
    {"$ref": "#/$defs/business_function"},
    {"$ref": "#/$defs/business_process"},
    {"$ref": "#/$defs/ict_service"},
    {"$ref": "#/$defs/information_asset"},
    {"$ref": "#/$defs/ict_asset"},
    {"$ref": "#/$defs/third_party_service"}
  ],
  "$defs": {
    "business_function": {
      "type": "object",
      "additionalProperties": false,
      "required": ["entity_id", "function_id", "name", "classification", "decision_owner", "classification_rationale"],
      "properties": {
        "entity_id": {"type": "string", "minLength": 1},
        "function_id": {"type": "string", "minLength": 1},
        "name": {"type": "string", "minLength": 1},
        "classification": {"enum": ["standard", "critical_or_important"]},
        "decision_owner": {"type": "string", "minLength": 1},
        "classification_rationale": {"type": "string", "minLength": 1}
      }
    },
    "business_process": {
      "type": "object",
      "additionalProperties": false,
      "required": ["entity_id", "process_id", "name", "owner_id"],
      "properties": {
        "entity_id": {"type": "string", "minLength": 1},
        "process_id": {"type": "string", "minLength": 1},
        "name": {"type": "string", "minLength": 1},
        "owner_id": {"type": "string", "minLength": 1}
      }
    },
    "ict_service": {
      "type": "object",
      "additionalProperties": false,
      "required": ["entity_id", "service_id", "name", "owner_id", "service_type"],
      "properties": {
        "entity_id": {"type": "string", "minLength": 1},
        "service_id": {"type": "string", "minLength": 1},
        "name": {"type": "string", "minLength": 1},
        "owner_id": {"type": "string", "minLength": 1},
        "service_type": {"type": "string", "minLength": 1}
      }
    },
    "information_asset": {
      "type": "object",
      "additionalProperties": false,
      "required": ["entity_id", "asset_id", "name", "owner_id", "classification"],
      "properties": {
        "entity_id": {"type": "string", "minLength": 1},
        "asset_id": {"type": "string", "minLength": 1},
        "name": {"type": "string", "minLength": 1},
        "owner_id": {"type": "string", "minLength": 1},
        "classification": {"type": "string", "minLength": 1}
      }
    },
    "ict_asset": {
      "type": "object",
      "additionalProperties": false,
      "required": ["entity_id", "asset_id", "name", "owner_id", "asset_type", "legacy"],
      "properties": {
        "entity_id": {"type": "string", "minLength": 1},
        "asset_id": {"type": "string", "minLength": 1},
        "name": {"type": "string", "minLength": 1},
        "owner_id": {"type": "string", "minLength": 1},
        "asset_type": {"type": "string", "minLength": 1},
        "legacy": {"type": "boolean"}
      }
    },
    "third_party_service": {
      "type": "object",
      "additionalProperties": false,
      "required": ["entity_id", "third_party_service_id", "provider_id", "name", "service_type", "direct_provider", "supply_chain_rank", "parent_third_party_service_id"],
      "properties": {
        "entity_id": {"type": "string", "minLength": 1},
        "third_party_service_id": {"type": "string", "minLength": 1},
        "provider_id": {"type": "string", "minLength": 1},
        "name": {"type": "string", "minLength": 1},
        "service_type": {"type": "string", "minLength": 1},
        "direct_provider": {"type": "boolean"},
        "supply_chain_rank": {"type": "integer", "minimum": 1},
        "parent_third_party_service_id": {"type": ["string", "null"], "minLength": 1}
      }
    }
  }
}

ict-risk.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://doraops.dev/schemas/ict-risk.schema.json",
  "title": "DORAOps ICT Risk Governance Artifact",
  "oneOf": [
    {"$ref": "#/$defs/scenario"},
    {"$ref": "#/$defs/control"},
    {"$ref": "#/$defs/policy"},
    {"$ref": "#/$defs/treatment"},
    {"$ref": "#/$defs/decision"}
  ],
  "$defs": {
    "sha256": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
    "node_ref": {
      "type": "object",
      "additionalProperties": false,
      "required": ["entity_id", "kind", "node_id"],
      "properties": {
        "entity_id": {"type": "string", "minLength": 1},
        "kind": {"enum": ["business_function", "business_process", "ict_service", "information_asset", "ict_asset", "third_party_service"]},
        "node_id": {"type": "string", "minLength": 1}
      }
    },
    "scenario": {
      "type": "object",
      "additionalProperties": false,
      "required": ["entity_id", "scenario_id", "title", "threat", "vulnerability", "risk_owner_id", "affected_nodes", "likelihood", "impact"],
      "properties": {
        "entity_id": {"type": "string", "minLength": 1},
        "scenario_id": {"type": "string", "minLength": 1},
        "title": {"type": "string", "minLength": 1},
        "threat": {"type": "string", "minLength": 1},
        "vulnerability": {"type": "string", "minLength": 1},
        "risk_owner_id": {"type": "string", "minLength": 1},
        "affected_nodes": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "#/$defs/node_ref"}},
        "likelihood": {"type": "integer", "minimum": 1, "maximum": 4},
        "impact": {"type": "integer", "minimum": 1, "maximum": 4}
      }
    },
    "control": {
      "type": "object",
      "additionalProperties": false,
      "required": ["entity_id", "control_id", "name", "control_type", "effectiveness", "evidence_digest"],
      "properties": {
        "entity_id": {"type": "string", "minLength": 1},
        "control_id": {"type": "string", "minLength": 1},
        "name": {"type": "string", "minLength": 1},
        "control_type": {"type": "string", "minLength": 1},
        "effectiveness": {"type": "integer", "minimum": 0, "maximum": 3},
        "evidence_digest": {"$ref": "#/$defs/sha256"}
      }
    },
    "policy": {
      "type": "object",
      "additionalProperties": false,
      "required": ["entity_id", "policy_id", "version", "medium_threshold", "high_threshold", "critical_threshold", "max_control_credit"],
      "properties": {
        "entity_id": {"type": "string", "minLength": 1},
        "policy_id": {"type": "string", "minLength": 1},
        "version": {"type": "string", "minLength": 1},
        "medium_threshold": {"type": "integer", "minimum": 2, "maximum": 16},
        "high_threshold": {"type": "integer", "minimum": 3, "maximum": 16},
        "critical_threshold": {"type": "integer", "minimum": 4, "maximum": 16},
        "max_control_credit": {"type": "integer", "minimum": 0, "maximum": 8}
      }
    },
    "treatment": {
      "type": "object",
      "additionalProperties": false,
      "required": ["treatment", "treatment_owner_id", "rationale", "target_timestamp"],
      "properties": {
        "treatment": {"enum": ["mitigate", "accept", "avoid", "transfer"]},
        "treatment_owner_id": {"type": "string", "minLength": 1},
        "rationale": {"type": "string", "minLength": 1},
        "target_timestamp": {"type": ["integer", "null"], "minimum": 0}
      }
    },
    "decision": {
      "type": "object",
      "additionalProperties": false,
      "required": ["entity_id", "scenario_id", "inventory_snapshot_digest", "scenario_digest", "policy_digest", "control_digests", "inherent_score", "inherent_level", "control_credit", "residual_score", "residual_level", "treatment", "risk_acceptance_required", "remediation_required"],
      "properties": {
        "entity_id": {"type": "string", "minLength": 1},
        "scenario_id": {"type": "string", "minLength": 1},
        "inventory_snapshot_digest": {"$ref": "#/$defs/sha256"},
        "scenario_digest": {"$ref": "#/$defs/sha256"},
        "policy_digest": {"$ref": "#/$defs/sha256"},
        "control_digests": {"type": "array", "uniqueItems": true, "items": {"$ref": "#/$defs/sha256"}},
        "inherent_score": {"type": "integer", "minimum": 1, "maximum": 16},
        "inherent_level": {"enum": ["low", "medium", "high", "critical"]},
        "control_credit": {"type": "integer", "minimum": 0, "maximum": 8},
        "residual_score": {"type": "integer", "minimum": 1, "maximum": 16},
        "residual_level": {"enum": ["low", "medium", "high", "critical"]},
        "treatment": {"$ref": "#/$defs/treatment"},
        "risk_acceptance_required": {"type": "boolean"},
        "remediation_required": {"type": "boolean"}
      }
    }
  }
}

resilience-test-plan.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://doraops.dev/schemas/resilience-test-plan.schema.json",
  "title": "DORAOps Resilience Test Plan",
  "type": "object",
  "additionalProperties": false,
  "required": ["entity_id", "test_id", "title", "test_type", "objective", "test_owner_id", "independent_reviewer_id", "inventory_snapshot_digest", "risk_decision_digests", "scope_nodes", "scenario", "planned_at", "tlpt_qualification_evidence_digest"],
  "properties": {
    "entity_id": {"type": "string", "minLength": 1},
    "test_id": {"type": "string", "minLength": 1},
    "title": {"type": "string", "minLength": 1},
    "test_type": {"enum": ["scenario_based", "vulnerability_assessment", "network_security_assessment", "penetration_test", "source_code_review", "physical_security_review", "performance_test", "end_to_end_test", "threat_led_penetration_test", "other"]},
    "objective": {"type": "string", "minLength": 1},
    "test_owner_id": {"type": "string", "minLength": 1},
    "independent_reviewer_id": {"oneOf": [{"type": "null"}, {"type": "string", "minLength": 1}]},
    "inventory_snapshot_digest": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
    "risk_decision_digests": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"type": "string", "pattern": "^[0-9a-f]{64}$"}},
    "scope_nodes": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"$ref": "#/$defs/nodeRef"}},
    "scenario": {"type": "string", "minLength": 1},
    "planned_at": {"type": "integer", "minimum": 0},
    "tlpt_qualification_evidence_digest": {"oneOf": [{"type": "null"}, {"type": "string", "pattern": "^[0-9a-f]{64}$"}]}
  },
  "$defs": {
    "nodeRef": {
      "type": "object",
      "additionalProperties": false,
      "required": ["entity_id", "kind", "node_id"],
      "properties": {
        "entity_id": {"type": "string", "minLength": 1},
        "kind": {"enum": ["business_function", "business_process", "ict_service", "information_asset", "ict_asset", "third_party_service"]},
        "node_id": {"type": "string", "minLength": 1}
      }
    }
  }
}

resilience-test-resolution.content:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://doraops.dev/schemas/resilience-test-resolution.schema.json",
  "title": "DORAOps Resilience Test Resolution",
  "type": "object",
  "additionalProperties": false,
  "required": ["plan_digest", "execution_digest", "state", "finding_resolutions", "unresolved_finding_digests", "evidence_history_digests"],
  "properties": {
    "plan_digest": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
    "execution_digest": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
    "state": {"enum": ["successful", "successful_with_findings", "blocked", "incomplete"]},
    "finding_resolutions": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["finding_digest", "status", "blocking", "remediation_digest", "retest_digest"],
        "properties": {
          "finding_digest": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
          "status": {"enum": ["open", "remediation_submitted", "retest_failed", "closed"]},
          "blocking": {"type": "boolean"},
          "remediation_digest": {"oneOf": [{"type": "null"}, {"type": "string", "pattern": "^[0-9a-f]{64}$"}]},
          "retest_digest": {"oneOf": [{"type": "null"}, {"type": "string", "pattern": "^[0-9a-f]{64}$"}]}
        }
      }
    },
    "unresolved_finding_digests": {"type": "array", "uniqueItems": true, "items": {"type": "string", "pattern": "^[0-9a-f]{64}$"}},
    "evidence_history_digests": {"type": "array", "uniqueItems": true, "items": {"type": "string", "pattern": "^[0-9a-f]{64}$"}}
  }
}
